//! The ASIO driver ABI: structures, constants and callback signatures.
//!
//! Written from the ASIO SDK headers (Steinberg, GPLv3 option; spec 0.2.2
//! ASIO-030) and checked against the bindings generated by asio-sys 0.4.0
//! (Apache-2.0). Integers are the Windows `long` (32 bits) of the SDK.

use std::ffi::c_void;

pub type AsioBool = i32;
pub type AsioErr = i32;

pub const ASE_OK: AsioErr = 0;
/// Success value of `future` calls.
pub const ASE_SUCCESS: AsioErr = 0x3f48_47a0;
pub const ASE_NOT_PRESENT: AsioErr = -1000;
pub const ASE_HW_MALFUNCTION: AsioErr = -999;
pub const ASE_INVALID_PARAMETER: AsioErr = -998;
pub const ASE_INVALID_MODE: AsioErr = -997;
pub const ASE_SP_NOT_ADVANCING: AsioErr = -996;
pub const ASE_NO_CLOCK: AsioErr = -995;
pub const ASE_NO_MEMORY: AsioErr = -994;

/// Text for an ASIO error code.
pub fn error_text(code: AsioErr) -> &'static str {
    match code {
        ASE_NOT_PRESENT => "the hardware input or output is not present",
        ASE_HW_MALFUNCTION => "the hardware is malfunctioning",
        ASE_INVALID_PARAMETER => "invalid parameter",
        ASE_INVALID_MODE => "the hardware is in a bad mode",
        ASE_SP_NOT_ADVANCING => "the hardware is not running",
        ASE_NO_CLOCK => "the sample clock cannot be determined",
        ASE_NO_MEMORY => "not enough memory",
        _ => "driver error",
    }
}

/// 64-bit sample position or system time split into two 32-bit halves.
#[repr(C)]
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Samples {
    pub hi: u32,
    pub lo: u32,
}

impl Samples {
    pub fn get(self) -> u64 {
        (u64::from(self.hi) << 32) | u64::from(self.lo)
    }
}

#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct ChannelInfo {
    /// Channel index, set by the caller.
    pub channel: i32,
    /// Set by the caller.
    pub is_input: AsioBool,
    pub is_active: AsioBool,
    pub channel_group: i32,
    pub sample_type: i32,
    /// Zero-terminated name.
    pub name: [u8; 32],
}

impl ChannelInfo {
    pub fn query(channel: i32, input: bool) -> Self {
        Self {
            channel,
            is_input: AsioBool::from(input),
            is_active: 0,
            channel_group: 0,
            sample_type: 0,
            name: [0; 32],
        }
    }

    pub fn name(&self) -> String {
        let end = self.name.iter().position(|b| *b == 0).unwrap_or(32);
        String::from_utf8_lossy(&self.name[..end]).trim().to_owned()
    }
}

/// One channel's double buffer; `buffers` are filled by the driver.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct BufferInfo {
    pub is_input: AsioBool,
    pub channel_num: i32,
    pub buffers: [*mut c_void; 2],
}

#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct TimeInfo {
    pub speed: f64,
    pub system_time: Samples,
    pub sample_position: Samples,
    pub sample_rate: f64,
    pub flags: u32,
    pub reserved: [u8; 12],
}

pub const SYSTEM_TIME_VALID: u32 = 1;
pub const SAMPLE_POSITION_VALID: u32 = 1 << 1;

#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct TimeCode {
    pub speed: f64,
    pub samples: Samples,
    pub flags: u32,
    pub future: [u8; 64],
}

#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct AsioTime {
    pub reserved: [i32; 4],
    pub time_info: TimeInfo,
    pub time_code: TimeCode,
}

/// The host's callbacks, given to `createBuffers`. C calling convention.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct Callbacks {
    pub buffer_switch: extern "C" fn(index: i32, direct: AsioBool),
    pub sample_rate_did_change: extern "C" fn(rate: f64),
    pub asio_message:
        extern "C" fn(selector: i32, value: i32, message: *mut c_void, opt: *mut f64) -> i32,
    pub buffer_switch_time_info:
        extern "C" fn(params: *mut AsioTime, index: i32, direct: AsioBool) -> *mut AsioTime,
}

// Message selectors of `asioMessage`.
pub const SELECTOR_SUPPORTED: i32 = 1;
pub const ENGINE_VERSION: i32 = 2;
pub const RESET_REQUEST: i32 = 3;
pub const BUFFER_SIZE_CHANGE: i32 = 4;
pub const RESYNC_REQUEST: i32 = 5;
pub const LATENCIES_CHANGED: i32 = 6;
pub const SUPPORTS_TIME_INFO: i32 = 7;
pub const SUPPORTS_TIME_CODE: i32 = 8;
pub const OVERLOAD: i32 = 15;

/// Sample types of driver channels (`ASIOSampleType`).
pub mod sample_type {
    pub const INT16_MSB: i32 = 0;
    pub const INT24_MSB: i32 = 1;
    pub const INT32_MSB: i32 = 2;
    pub const FLOAT32_MSB: i32 = 3;
    pub const FLOAT64_MSB: i32 = 4;
    pub const INT32_MSB16: i32 = 8;
    pub const INT32_MSB18: i32 = 9;
    pub const INT32_MSB20: i32 = 10;
    pub const INT32_MSB24: i32 = 11;
    pub const INT16_LSB: i32 = 16;
    pub const INT24_LSB: i32 = 17;
    pub const INT32_LSB: i32 = 18;
    pub const FLOAT32_LSB: i32 = 19;
    pub const FLOAT64_LSB: i32 = 20;
    pub const INT32_LSB16: i32 = 24;
    pub const INT32_LSB18: i32 = 25;
    pub const INT32_LSB20: i32 = 26;
    pub const INT32_LSB24: i32 = 27;
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::mem::{align_of, offset_of, size_of};

    /// Layouts of the SDK structures on 64-bit Windows (and any 64-bit
    /// target with 8-byte pointers).
    #[test]
    fn layouts_match_the_sdk() {
        assert_eq!(size_of::<Samples>(), 8);
        assert_eq!(size_of::<ChannelInfo>(), 52);
        assert_eq!(offset_of!(ChannelInfo, name), 20);
        assert_eq!(size_of::<BufferInfo>(), 24);
        assert_eq!(offset_of!(BufferInfo, buffers), 8);
        assert_eq!(size_of::<TimeInfo>(), 48);
        assert_eq!(offset_of!(TimeInfo, sample_position), 16);
        assert_eq!(offset_of!(TimeInfo, flags), 32);
        assert_eq!(size_of::<TimeCode>(), 88);
        assert_eq!(size_of::<AsioTime>(), 152);
        assert_eq!(offset_of!(AsioTime, time_info), 16);
        assert_eq!(offset_of!(AsioTime, time_code), 64);
        assert_eq!(size_of::<Callbacks>(), 32);
        assert_eq!(align_of::<AsioTime>(), 8);
    }

    #[test]
    fn samples_and_names() {
        assert_eq!(Samples { hi: 1, lo: 2 }.get(), (1 << 32) + 2);
        let mut c = ChannelInfo::query(3, true);
        c.name[..6].copy_from_slice(b"Mic 1 ");
        assert_eq!(c.name(), "Mic 1");
        assert_eq!(c.is_input, 1);
    }
}
